ROOT.functiondef:
CREATE   function CDN.SrtZmniejszeniaAmWDanymRoku(@SrtNumer int, @DataRozp int, @DataNaDzien int, @Tor smallint = 0, @DataDok int = null, @ZestTryb tinyint = 0, @WartoscSys tinyint = 0)
returns decimal(15,2)
AS
BEGIN
	------------------------------------------------------------------------------------------------------
	--------	 funkcja zwraca kwotę zwiększeń dla amortyzacji		--------
	---
	--- @Tor = 0  - amortyzacja bilansowa
	--- @Tor = 1  - amortyzacja podatkowa
	---
	--- funkcja wykorzystywana w:
	---  > wydrukach srt: tabela amoryzacji (z poziomu zakładki generacja i z poziomu zakładki grupy),
	------------------------------------------------------------------------------------------------------

	-- @ZestTryb	 -	<> 2 - szukaj dla środka trwałego, 2 - szukaj dla elementu zestawu

  declare @wynik decimal(15,2);
  declare @ZO int;
  declare @ZM int;
  declare @PK int;
  declare @OT int;
  declare @OTK int;
  declare @LT int;
  declare @LTK int;
  declare @AM int;
  declare @AMK int;
  declare @AMP int;
  declare @AK int;
  declare @MW int;
  declare @MWK int;
  declare @ZPA int;
  declare @ZPK int;

  set  @ZO = 2144;
  set  @ZM = 2160;
  set  @OT = 2048;
  set  @OTK = 2176;
  set  @PK = 2080;
  set  @LT = 2096;
  set  @LTK = 2224;
  set  @AM = 2064;
  set  @AMK = 2192;
  set  @AMP = 6208;
  set  @AK = 2304;
  set  @MW = 2432;
  set  @MWK = 2496;
  set  @ZPA = 2050;
  set  @ZPK = 2051;
  
  
  declare @ZestTrybSrodek  tinyint = 0  
  declare @ZestTrybZestaw  tinyint = 1
  declare @ZestTrybElement tinyint = 2
    
  declare @ZestOdlaczenie	tinyint = 1
  declare @ZestPrzylaczenie	tinyint = 2
  
  declare @zmianaWaluty tinyint = 0
  
  if @ZestTryb = 0		-- dla środka trwałego sprawdzenie, czy była zmiana waluty (wielowalutowość zestawów)
		if exists (select 1 from cdn.SrtZestElem where SZE_SrtNumer = @SrtNumer and SZE_Waluta <> SZE_OrgWaluta and SZE_DataPrzylaczenia between @DataRozp and @DataNaDzien)
			select @zmianaWaluty = 1

  if @Tor = 0
     set @wynik =
      isnull(
		(
			select sum(case when she_gidtyp = @LT then -1 else 1 end * case when @zmianaWaluty = 1 or @WartoscSys = 1 then SHE_KwotaUmSys else SHE_KwotaUm end) from cdn.srthistelem 
			where ( ( (she_gidtyp in  (@AM,@AMK,@AMP,@MW,@MWK,@PK,@AK) or SHE_GIDTyp in (@ZPA, @ZPK) and @ZestTryb in (@ZestTrybSrodek, @ZestTrybZestaw)) and she_kwotaUm<0) OR
					 (she_gidtyp = @LT or SHE_GIDTyp in (@ZPA, @ZPK) and SHE_PrzesStrona = @ZestOdlaczenie and @ZestTryb in (@ZestTrybSrodek, @ZestTrybZestaw) and she_kwotaUm>0 ) )
				and she_srtnumer=@SrtNumer and she_data>=@DataRozp and she_data<=@DataNaDzien
				and (isnull(@DataDok,0) = 0 or isnull(@DataDok,0) <> 0  and she_dataZap <= @DataDok)),0)
  else
     set @wynik =
      isnull((select sum(case when she_gidtyp = @LT then -1 else 1 end * case when @zmianaWaluty = 1 or @WartoscSys = 1 then SHE_KwotaAmSys else SHE_KwotaAm end) from cdn.srthistelem 
			where (( (she_gidtyp in (@AM,@AMK,@AMP,@MW,@MWK,@PK,@AK) or SHE_GIDTyp in (@ZPA, @ZPK) and @ZestTryb in (@ZestTrybSrodek, @ZestTrybZestaw) and SHE_PrzesStrona = @ZestPrzylaczenie ) and she_kwotaAm<0) OR
				(she_gidtyp = @LT or SHE_GIDTyp in (@ZPA, @ZPK) and SHE_PrzesStrona = @ZestOdlaczenie and @ZestTryb in (@ZestTrybSrodek, @ZestTrybZestaw) and she_kwotaAm>0)) and she_srtnumer=@SrtNumer and she_data>=@DataRozp and she_data<=@DataNaDzien and
				(isnull(@DataDok,0) = 0 or isnull(@DataDok,0) <> 0  and she_dataZap <= @DataDok)),0)

    return(@wynik)
END
